"""Demo: classify every statement of the concrete multiverse.

Reports, for each statement, its modality (multiverse-true / -false /
independent) and verifies the equivalence independence <=> undeterminedness.
"""
from __future__ import annotations
from typing import Dict, Tuple

Universe = str
Statement = str
TABLE: Dict[Tuple[Universe, Statement], bool] = {
    ("L", "ZFC"): True, ("L", "CH"): True, ("L", "VeqL"): True, ("L", "LargeCardinal"): False,
    ("cohen", "ZFC"): True, ("cohen", "CH"): False, ("cohen", "VeqL"): False, ("cohen", "LargeCardinal"): False,
    ("measurable", "ZFC"): True, ("measurable", "CH"): True, ("measurable", "VeqL"): False, ("measurable", "LargeCardinal"): True,
}
UNIVERSES = ("L", "cohen", "measurable")
STATEMENTS = ("ZFC", "CH", "VeqL", "LargeCardinal")


def multiverse_true(s: Statement) -> bool:
    return all(TABLE[(u, s)] for u in UNIVERSES)


def multiverse_false(s: Statement) -> bool:
    return all(not TABLE[(u, s)] for u in UNIVERSES)


def independent(s: Statement) -> bool:
    return any(TABLE[(u, s)] for u in UNIVERSES) and any(not TABLE[(u, s)] for u in UNIVERSES)


def undetermined(s: Statement) -> bool:
    return not multiverse_true(s) and not multiverse_false(s)


def main() -> None:
    for s in STATEMENTS:
        assert independent(s) == undetermined(s)  # Theorem: Ind <=> Und
        label = ("multiverse-true" if multiverse_true(s)
                 else "multiverse-false" if multiverse_false(s)
                 else "independent/undetermined")
        print(f"{s:14s}: {label}")
    print("\nNo true CH:", undetermined("CH"))
    print("ZFC determined:", multiverse_true("ZFC"))


if __name__ == "__main__":
    main()

"""Demo: forcing closure forces undeterminedness.

A statement is forcing-closed if every universe has a forcing neighbor with
the opposite truth value. We verify CH is forcing-closed and ZFC is not, and
conclude undeterminedness for CH.
"""
from __future__ import annotations
from typing import Dict, List

UNIVERSES = ["L", "cohen", "measurable"]
TRUTH: Dict[str, Dict[str, bool]] = {
    "CH": {"L": True, "cohen": False, "measurable": True},
    "ZFC": {"L": True, "cohen": True, "measurable": True},
}


def forcing_closed(truth: Dict[str, bool], neighbor: Dict[str, str]) -> bool:
    return all(truth[neighbor[u]] != truth[u] for u in UNIVERSES)


def undetermined(truth: Dict[str, bool]) -> bool:
    vals = list(truth.values())
    return any(vals) and not all(vals)


def main() -> None:
    ch_neighbors = {"L": "cohen", "cohen": "L", "measurable": "cohen"}
    fc = forcing_closed(TRUTH["CH"], ch_neighbors)
    print("CH forcing-closed:", fc)
    if fc:
        print("  => CH undetermined:", undetermined(TRUTH["CH"]))
    # ZFC: try every neighbor map; none can flip a constant-true statement.
    zfc_neighbors = {"L": "cohen", "cohen": "measurable", "measurable": "L"}
    print("ZFC forcing-closed:", forcing_closed(TRUTH["ZFC"], zfc_neighbors))
    print("ZFC undetermined:", undetermined(TRUTH["ZFC"]))


if __name__ == "__main__":
    main()

