function TROPICAL_SIGNATURE(universes, holds):
    beta(b) := 0 if b else +INF
    trop_sum  <- +INF          # additive unit
    trop_prod <- 0             # multiplicative unit
    for u in universes:
        v <- beta(holds(u))
        trop_sum  <- min(trop_sum, v)   # tropical +
        trop_prod <- trop_prod + v      # tropical *
    possible  <- (trop_sum  == 0)
    necessary <- (trop_prod == 0)
    if necessary: return (trop_sum, trop_prod, MULTIVERSE_TRUE)
    if not possible: return (trop_sum, trop_prod, MULTIVERSE_FALSE)
    return (trop_sum, trop_prod, INDEPENDENT)

function IS_FORCING_CLOSED(universes, holds, neighbor):
    for u in universes:
        if holds(neighbor[u]) == holds(u):
            return FALSE      # this universe has no flipping extension
    return TRUE

function UNDETERMINED_VIA_FORCING(universes, holds, neighbor):
    return IS_FORCING_CLOSED(universes, holds, neighbor)  # closure => undetermined

