from typing import Callable, Dict, List

def is_forcing_closed(
    universes: List[str],
    holds: Callable[[str], bool],
    neighbor: Dict[str, str],
) -> bool:
    """Certify forcing closure of a statement.

    'neighbor[u]' is a forcing extension of u. The statement is
    forcing-closed iff every universe's neighbor has the opposite truth
    value; forcing closure implies the statement is undetermined.
    Complexity: O(|universes|).
    """
    return all(holds(neighbor[u]) != holds(u) for u in universes)


def undetermined_via_forcing(
    universes: List[str],
    holds: Callable[[str], bool],
    neighbor: Dict[str, str],
) -> bool:
    """Return True if forcing closure certifies undeterminedness."""
    return is_forcing_closed(universes, holds, neighbor)
